def rank(a,m,n):
 a=[row[:] for row in a];r=0
 for j in range(n):
  pivot=next((i for i in range(r,m) if a[i][j]),None)
  if pivot is None:continue
  a[r],a[pivot]=a[pivot],a[r];d=a[r][j]
  for k in range(j,n):a[r][k]/=d
  for i in range(r+1,m):
   q=a[i][j]
   for k in range(j,n):a[i][k]-=q*a[r][k]
  r+=1
  if r==m:break
 return r

def certify(a,m,n,p,l,d,u):
 required={'P':[m,m],'L':[m,m],'D':[m,m],'U':[m,n]}
 shapes=all(len(v)==required[k][0] and all(len(row)==required[k][1] for row in v) for k,v in [('P',p),('L',l),('D',d),('U',u)])
 if not shapes:return {'shapes':False,'complete_certificate':False}
 permutation=all(v in (0,1) for row in p for v in row) and all(sum(row)==1 for row in p) and all(sum(p[i][j] for i in range(m))==1 for j in range(m))
 lower=all(l[i][j]==0 for i in range(m) for j in range(i+1,m));diagonal=all(d[i][j]==0 for i in range(m) for j in range(m) if i!=j)
 invertible_d=all(d[i][i]!=0 for i in range(m));invertible_l=all(l[i][i]!=0 for i in range(m))
 upper=all(u[i][j]==0 for i in range(m) for j in range(min(i,n)))
 pivots=[];echelon=True
 for i,row in enumerate(u):
  col=next((j for j,v in enumerate(row) if v),None)
  if col is None:continue
  if i!=len(pivots):echelon=False
  if any(u[k][col] for k in range(i+1,m)):echelon=False
  pivots.append(col)
 echelon=echelon and pivots==sorted(set(pivots))
 pa=[[sum(p[i][k]*a[k][j] for k in range(m)) for j in range(n)] for i in range(m)]
 lhs=None;identity=False;wrong=[]
 if diagonal and invertible_d:
  lhs=[[sum(l[i][k]*u[k][j]/d[k][k] for k in range(m)) for j in range(n)] for i in range(m)]
  identity=pa==lhs
  wrong=[{'index':[i,j],'P_A':str(pa[i][j]),'L_Dinv_U':str(lhs[i][j])} for i in range(m) for j in range(n) if pa[i][j]!=lhs[i][j]]
 ra,ru=rank(a,m,n),rank(u,m,n);ranks=ra==ru==len(pivots)
 return {'shapes':shapes,'permutation':permutation,'L_lower':lower,'D_diagonal':diagonal,'D_invertible':invertible_d,'L_invertible':invertible_l,'U_upper':upper,'U_echelon':echelon,'pivot_columns':pivots,'rank_A':ra,'rank_U':ru,'rank_complete':ranks,'P_A_equals_L_Dinv_U':identity,'mismatches':wrong,'complete_certificate':all([shapes,permutation,lower,diagonal,invertible_d,invertible_l,upper,echelon,ranks,identity])}

def packed_factors(lu,perm,m,n):
 u=[row[:] for row in lu];p=[[Fraction(int(perm[i]==j)) for j in range(m)] for i in range(m)];l=[[Fraction(0) for j in range(m)] for i in range(m)];i=0
 for j in range(n):
  if i==m:break
  if u[i][j]:
   l[i][i]=u[i][j]
   for k in range(i+1,m):l[k][i]=u[k][j];u[k][j]=Fraction(0)
   i+=1
 for k in range(i,m):l[k][k]=Fraction(1)
 d=[[Fraction(0) for j in range(m)] for i in range(m)]
 if m:d[0][0]=l[0][0]
 for k in range(1,m):d[k][k]=l[k-1][k-1]*l[k][k]
 return p,l,d,u


def numbers(rows):return [[Fraction(str(v)) for v in row] for row in rows]
def cells(rows,k):
    return [[k(Fraction(v).numerator,Fraction(v).denominator) if k==sx.QQ else k(int(Fraction(v))) for v in row] for row in rows]
def source(case,entry):
    k=getattr(sx,case['domain']);m,n=case['shape'];a=DDM(cells(case['rows'],k),(m,n),k)
    if entry=='ddm':return a
    a=DomainMatrix.from_rep(a)
    return a.to_sparse() if entry=='sparse' else a

def values(a):return numbers(a.to_list() if isinstance(a,DomainMatrix) else a)

def alias_graph(matrices):
    ids={}
    def token(value):return ids.setdefault(id(value),len(ids))
    out=[]
    for a in matrices:
        rep=a.rep if isinstance(a,DomainMatrix) else a
        if isinstance(rep,dict):out.append(['sparse',token(rep),[[i,token(row),[[j,token(v)] for j,v in row.items()]] for i,row in rep.items()]])
        else:out.append(['dense',token(rep),[[token(row),[token(v) for v in row]] for row in rep]])
    return out


def python_function(name):
    tree=ast.parse(Path(ddm_module.__file__).read_text())
    cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='DDM')
    node=copy.deepcopy(next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name==name))
    body=[]
    for statement in node.body:
        if isinstance(statement,ast.If) and isinstance(statement.test,ast.Call) and isinstance(statement.test.func,ast.Name) and statement.test.func.id=='_native_fflu':continue
        if isinstance(statement,ast.If) and isinstance(statement.test,ast.UnaryOp) and isinstance(statement.test.op,ast.Not) and isinstance(statement.test.operand,ast.Call) and isinstance(statement.test.operand.func,ast.Name) and statement.test.operand.func.id.startswith('_native_fflu_'):
            body.extend(statement.body)
        else:body.append(statement)
    node.body=body
    code=compile(ast.fix_missing_locations(ast.Module(body=[node],type_ignores=[])),ddm_module.__file__,'exec')
    return types.FunctionType(next(c for c in code.co_consts if type(c)is types.CodeType),ddm_module.__dict__)


@pytest.mark.parametrize('entry',['ddm','dense','sparse'])
@pytest.mark.parametrize('case',CASES,ids=lambda c:c['id'])
def test_complete_public_factorization_canonical_pivots_and_first_native_routes(case,entry,monkeypatch):
    a=source(case,entry);before=values(a);calls=[]
    for name in NATIVE_NAMES:
        native=getattr(sx._core,name)
        def record(*args,_name=name,_native=native,**kwargs):
            result=_native(*args,**kwargs);calls.append((_name,result));return result
        monkeypatch.setattr(sx._core,name,record)
    out=a.fflu()
    assert calls==[(name,True) for name in NATIVE_NAMES]
    actual=[values(v) for v in out]
    assert actual==[numbers(case['factors'][name]) for name in 'PLDU']
    m,n=case['shape'];proof=certify(before,m,n,*actual)
    assert proof['complete_certificate'] and proof['rank_A']==case['rank'] and proof['pivot_columns']==case['pivots']
    assert all(v.domain is a.domain for v in out)
    assert values(a)==before
    if entry=='sparse':assert all(v.rep.fmt=='sparse' for v in out)
    elif entry=='dense':assert all(v.rep.fmt=='dense' for v in out)


@pytest.mark.parametrize('case',CASES,ids=lambda c:c['id'])
def test_private_packed_format_permutation_and_source_aliases(case,monkeypatch):
    a=source(case,'ddm');before=values(a);rows=list(a);cell_ids=[[id(v) for v in row] for row in a];calls=[];native=sx._core._ddm_fflu
    def record(*args):
        result=native(*args);calls.append(result);return result
    monkeypatch.setattr(sx._core,'_ddm_fflu',record)
    lu,perm=a._fflu()
    assert calls==[True] and values(lu)==numbers(case['packed']) and perm==case['perm']
    assert lu.shape==a.shape and lu.domain is a.domain and lu is not a
    assert values(a)==before and all(row is original for row,original in zip(a,rows))
    assert cell_ids==[[id(v) for v in row] for row in a]


@pytest.mark.parametrize('case',[c for c in CASES if c['id'].startswith(('wide-delayed-pivot-','skipped-denominator-','orientation-cycle-','rational-'))],ids=lambda c:c['id'])
def test_missing_metadata_keeps_complete_corrected_python_factorization(case,monkeypatch):
    a=source(case,'ddm');monkeypatch.setattr(sx._core,'_ddm_function_metadata',None)
    for name in NATIVE_NAMES:monkeypatch.setattr(sx._core,name,lambda *a:pytest.fail('missing metadata must use complete generic math'))
    out=a.fflu();assert [values(v) for v in out]==[numbers(case['factors'][name]) for name in 'PLDU']
    assert certify(numbers(case['rows']),*case['shape'],*[values(v) for v in out])['complete_certificate']


@pytest.mark.parametrize('case',[c for c in CASES if c['id'].startswith(('wide-delayed-pivot-','skipped-denominator-','orientation-cycle-'))],ids=lambda c:c['id'])
def test_all_factor_object_aliases_match_corrected_python_body(case):
    a=source(case,'ddm');b=source(case,'ddm')
    pure_private=python_function('_fflu');pure_public=python_function('fflu')
    b._fflu=types.MethodType(pure_private,b)
    actual=a.fflu();expected=pure_public(b)
    assert [values(v) for v in actual]==[values(v) for v in expected]
    assert alias_graph([a,*actual])==alias_graph([b,*expected])


@pytest.mark.parametrize('shape',[(0,0),(0,2**130),(3,0)])
def test_empty_shapes_preserve_arbitrary_dimensions_without_zero_clamping(shape):
    m,n=shape;a=DDM([[] for _ in range(m)],shape,sx.ZZ);p,l,d,u=a.fflu()
    assert u.shape==shape and p.shape==l.shape==d.shape==(m,m)
    assert values(u)==[[] for _ in range(m)]


def test_copy_and_zeros_barriers_run_once_with_completed_publication():
    a=DDM(cells([[0,0,1,2],[0,0,2,3]],sx.ZZ),(2,4),sx.ZZ);events=[];saved=[];original_copy=a.copy;original_zeros=a.zeros
    def copy_once():events.append('copy');return original_copy()
    def zeros(shape,k):
        events.append('zeros')
        if saved:
            if len(saved)==1:assert values(saved[0])==[[1,0],[0,1]]
            if len(saved)==2:assert values(saved[1])==[[1,0],[2,-1]]
        out=original_zeros(shape,k);saved.append(out);return out
    a.copy=copy_once;a.zeros=zeros
    p,l,d,u=a.fflu()
    assert events==['copy','zeros','zeros','zeros'] and saved==[p,l,d]


def test_generic_GF_and_polynomial_domains_keep_complete_fallback(monkeypatch):
    for name in NATIVE_NAMES:
        native=getattr(sx._core,name)
        def record(*args,_native=native,**kwargs):
            result=_native(*args,**kwargs);assert result is False;return result
        monkeypatch.setattr(sx._core,name,record)
    for k in [sx.GF(7),sx.ZZ.poly_ring('x')]:
        a=DDM([[k(1),k(2)],[k(3),k(4)]],(2,2),k);before=a.copy();p,l,d,u=a.fflu()
        assert a==before and all(v.domain is k for v in (p,l,d,u))
        # This exact ring certificate clears D without constructing an inverse.
        denominator=d[0][0]*d[1][1]
        for i in range(2):
            for j in range(2):
                left=denominator*sum((p[i][r]*before[r][j] for r in range(2)),k.zero)
                right=sum((l[i][r]*u[r][j]*d[1-r][1-r] for r in range(2)),k.zero)
                assert left==right


PROTOCOL_SCRIPT="import ast,builtins,copy,importlib,json,sys,types\nfrom pathlib import Path\nfrom fractions import Fraction\nimport symox as sx\nfrom symox.polys.matrices.ddm import DDM\nddm_module=importlib.import_module('symox.polys.matrices.ddm')\nprinting=importlib.import_module('symox.polys.domains._element_print')\nalgebraic=importlib.import_module('symox.polys.domains._algebraic_methods')\nNATIVE_NAMES=('_ddm_fflu','_ddm_fflu_p','_ddm_fflu_l','_ddm_fflu_d')\ndef python_function(name):\n    tree=ast.parse(Path(ddm_module.__file__).read_text())\n    cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='DDM')\n    node=copy.deepcopy(next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name==name))\n    body=[]\n    for statement in node.body:\n        if isinstance(statement,ast.If) and isinstance(statement.test,ast.Call) and isinstance(statement.test.func,ast.Name) and statement.test.func.id=='_native_fflu':continue\n        if isinstance(statement,ast.If) and isinstance(statement.test,ast.UnaryOp) and isinstance(statement.test.op,ast.Not) and isinstance(statement.test.operand,ast.Call) and isinstance(statement.test.operand.func,ast.Name) and statement.test.operand.func.id.startswith('_native_fflu_'):\n            body.extend(statement.body)\n        else:body.append(statement)\n    node.body=body\n    code=compile(ast.fix_missing_locations(ast.Module(body=[node],type_ignores=[])),ddm_module.__file__,'exec')\n    return types.FunctionType(next(c for c in code.co_consts if type(c)is types.CodeType),ddm_module.__dict__)\nmode,target=sys.argv[1:3]\na=DDM([[sx.ZZ(v) for v in row] for row in [[0,0,1,2],[0,0,2,3]]],(2,4),sx.ZZ)\nb=DDM([[sx.ZZ(v) for v in row] for row in [[0,0,1,2],[0,0,2,3]]],(2,4),sx.ZZ)\npure_private=python_function('_fflu');pure_public=python_function('fflu');b._fflu=types.MethodType(pure_private,b)\ncore=sx._core;events=[];calls=[];audit_events=[];restore_core=False\nfor name in NATIVE_NAMES:\n native=getattr(core,name)\n def record(*args,_name=name,_native=native,**kwargs):\n  result=_native(*args,**kwargs);calls.append((_name,result));return result\n setattr(core,name,record)\nowner=algebraic if target=='_exquo' else printing\noriginal=owner.__dict__.get(target)\nclass TupleSubclass(tuple):\n def __len__(self):events.append('tuple-len');raise AssertionError('tuple-len')\n def __iter__(self):events.append('tuple-iter');raise AssertionError('tuple-iter')\n def __getitem__(self,key):events.append('tuple-getitem');raise AssertionError('tuple-getitem')\n def __eq__(self,other):events.append('tuple-eq');raise AssertionError('tuple-eq')\nclass DictSubclass(dict):\n def __getitem__(self,key):events.append('dict-getitem');raise AssertionError('dict-getitem')\n def __iter__(self):events.append('dict-iter');raise AssertionError('dict-iter')\n def __len__(self):events.append('dict-len');raise AssertionError('dict-len')\ndef replace_function(function):\n owner.__dict__[target]=function\n if target in ('_eq','_ne'):setattr(core.DomainElement,'__'+target.strip('_')+'__',function)\n if target=='_exquo':core.Domain.exquo=function\nif mode in ('closure','defaults','kwdefaults','consts','cached-builtins'):\n code,namespace,name,defaults=original.__code__,original.__globals__,original.__name__,original.__defaults__\n if mode=='closure':function=types.FunctionType(code,namespace,name,defaults,TupleSubclass(()))\n elif mode=='defaults':function=types.FunctionType(code,namespace,name,TupleSubclass(()))\n elif mode=='kwdefaults':\n  function=types.FunctionType(code,namespace,name,defaults);function.__kwdefaults__=DictSubclass()\n elif mode=='consts':function=types.FunctionType(code.replace(co_consts=TupleSubclass(code.co_consts)),namespace,name,defaults)\n else:\n  original_builtins=namespace['__builtins__'];foreign=dict(builtins.__dict__)\n  def observed_type(*args):events.append('cached-type');return type(*args)\n  foreign['type']=observed_type\n  namespace['__builtins__']=foreign\n  try:function=types.FunctionType(code,namespace,name,defaults)\n  finally:namespace['__builtins__']=original_builtins\n replace_function(function)\nelif mode=='changed-before-import':\n saved=types.FunctionType(original.__code__,original.__globals__,original.__name__,original.__defaults__)\n owner.__dict__['_fflu_test_events']=events;owner.__dict__['_fflu_test_saved']=saved\n def observer(*args):\n  _fflu_test_events.append('changed-code');return _fflu_test_saved(*args)\n original.__code__=observer.__code__\nelif mode=='metadata-object':\n class Foreign:\n  def __getattribute__(self,name):events.append('foreign-getattr');raise AssertionError(name)\n core.__dict__['_ddm_function_metadata']=Foreign()\nelif mode=='core-key':\n key_hash=hash('_ddm_function_metadata');core.__dict__.pop('_ddm_function_metadata')\n class ForeignKey:\n  def __hash__(self):return key_hash\n  def __eq__(self,other):events.append('foreign-eq');raise AssertionError('foreign-eq')\n core.__dict__[ForeignKey()]=17\nelif mode=='core-module':\n from types import ModuleType\n class ForeignModule(ModuleType):\n  def __getattribute__(self,name):events.append('foreign-module');raise RuntimeError(name)\n core.__class__=ForeignModule;restore_core=True\nif mode=='changed-before-import' or target=='preimport':\n module_name='symox.polys.matrices._fflu_native';sys.modules.pop(module_name,None);guard=importlib.import_module(module_name);guard.register(DDM)\n for name,function in [('_native_fflu',guard.try_eliminate),('_native_fflu_p',guard.try_permutation),('_native_fflu_l',guard.try_lower),('_native_fflu_d',guard.try_diagonal)]:setattr(ddm_module,name,function)\nif mode=='audit':\n def audit(event,args):\n  if event=='object.__getattr__':audit_events.append(args[1]);raise AssertionError('speculative audit '+args[1])\n sys.addaudithook(audit)\ndef execute(function):\n events.clear();calls.clear()\n try:out=function()\n except Exception as error:return {'error':type(error).__name__,'message':str(error)},events[:],calls[:]\n observed_events=events[:];observed_calls=calls[:]\n values=[[[str(Fraction(str(v))) for v in row] for row in factor] for factor in out]\n return {'factors':values},observed_events,observed_calls\nactual,actual_events,actual_calls=execute(a.fflu)\nexpected,expected_events,expected_calls=execute(lambda:pure_public(b))\nif restore_core:core.__class__=ModuleType\nassert actual==expected,(mode,target,actual,expected)\nassert actual_events==expected_events,(mode,target,actual_events,expected_events)\nassert expected_calls==[]\nassert not any(n=='sympy' or n.startswith('sympy.') for n in sys.modules)\nprint(json.dumps({'mode':mode,'target':target,'actual':actual,'actual_events':actual_events,'native_calls':actual_calls,'expected_events':expected_events,'audit_events':audit_events,'reference_imported':False}))\n"


@pytest.mark.parametrize('mode,target',[('audit','_eq')]+[(mode,target) for mode in ('closure','defaults','kwdefaults','consts','cached-builtins','changed-before-import') for target in ('_int_congruent','_eq','_ne','_exquo')]+[(mode,phase) for mode in ('metadata-object','core-key','core-module') for phase in ('call','preimport')])
def test_metadata_protocol_controls_have_no_added_observations_and_full_results(mode,target):
    result=subprocess.run([sys.executable,'-c',PROTOCOL_SCRIPT,mode,target],env=dict(os.environ,PYTHONPATH=str(Path(sx.__file__).resolve().parents[1])),capture_output=True,text=True,timeout=45)
    assert result.returncode==0,result.stderr
    data=json.loads(result.stdout)
    assert data['reference_imported'] is False and data['audit_events']==[]
    if mode=='audit':assert data['native_calls']==[[name,True] for name in NATIVE_NAMES]
    else:assert data['native_calls']==[]
    if mode in ('closure','defaults','kwdefaults','consts','metadata-object','core-key'):assert data['actual_events']==[] and 'factors' in data['actual']


@pytest.mark.parametrize('domain',['ZZ','QQ'])
def test_unbounded_exact_coefficients_and_rational_denominators(domain,monkeypatch):
    big=2**768+49
    integer_rows=[[0,big+2,big+3,big+5],[0,big+7,big+11,big+13],[0,big+17,big+19,big+23]]
    rows=integer_rows if domain=='ZZ' else [[Fraction(v,big+29) for v in row] for row in integer_rows]
    k=getattr(sx,domain);a=DDM(cells(rows,k),(3,4),k);calls=[]
    for name in NATIVE_NAMES:
        native=getattr(sx._core,name)
        def record(*args,_name=name,_native=native,**kwargs):
            result=_native(*args,**kwargs);calls.append((_name,result));return result
        monkeypatch.setattr(sx._core,name,record)
    p,l,d,u=a.fflu()
    assert calls==[(name,True) for name in NATIVE_NAMES]
    proof=certify(numbers(rows),3,4,*[values(v) for v in (p,l,d,u)])
    assert proof['complete_certificate'] and proof['rank_A']==3 and proof['pivot_columns']==[1,2,3]
    assert all(v.domain is k for v in (p,l,d,u)) and values(a)==numbers(rows)
